#!/usr/bin/env python3
"""Render the two checklist views from the canonical JSON, or check for drift."""
from pathlib import Path
import argparse
import html
import json

HTML_TEMPLATE = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Speed of Sound — handoff checklist</title><style>\n:root{color-scheme:light;--ink:#182d3b;--muted:#566b76;--line:#dce4e5;--paper:#fff;--base:#f3f6f5;--accent:#0d655c}\n*{box-sizing:border-box}body{margin:0;background:var(--base);color:var(--ink);font:16px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:940px;margin:auto;padding:38px 24px 56px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}h1{font-size:clamp(28px,5vw,40px);letter-spacing:-.04em;line-height:1.12;margin:9px 0 12px}h2{font-size:19px;letter-spacing:-.02em;margin:0}.intro{max-width:730px;color:var(--muted);margin:0 0 20px}.repo{display:block;overflow-wrap:anywhere;font-size:12px;margin:8px 0 3px}.context{border:1px solid var(--line);border-radius:12px;background:#fff;padding:14px 18px;margin:20px 0}.context strong{font-size:14px}.context p{margin:6px 0;color:var(--muted);font-size:13px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:18px 0 6px}button{font:inherit;font-size:13px;font-weight:650;border:1px solid var(--line);background:#fff;color:var(--ink);padding:9px 13px;border-radius:7px;cursor:pointer}button.primary{background:var(--accent);color:white;border-color:var(--accent)}button:hover{filter:brightness(.97)}button:focus-visible,input:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #83b9b3;outline-offset:3px}.toggle{font-size:13px;display:flex;gap:7px;align-items:center;margin-left:auto}.toggle input{accent-color:var(--accent)}.save-status{font-size:12px;color:var(--muted);min-height:20px;margin:0 0 18px}.progress-card{border-radius:12px;background:var(--ink);color:#fff;padding:18px 20px;margin:22px 0}.progress-title{display:flex;justify-content:space-between;align-items:baseline;gap:12px}.progress-title strong{font-size:16px}.progress-title span{font-size:13px;color:#d7e4e7}progress{width:100%;height:8px;border:0;border-radius:99px;background:#3e525c;margin-top:12px;overflow:hidden}progress::-webkit-progress-bar{background:#3e525c}progress::-webkit-progress-value{background:#99d5bc}progress::-moz-progress-bar{background:#99d5bc}.progress-note{font-size:12px;color:#d7e4e7;margin:7px 0 0}.phase{margin:22px 0}.phase-heading{display:flex;align-items:baseline;justify-content:space-between;gap:15px;margin:0 0 9px}.phase-count{font-size:12px;color:var(--muted)}.task-list{background:var(--paper);border:1px solid var(--line);border-radius:12px;overflow:hidden}.task{padding:15px 18px;border-bottom:1px solid var(--line)}.task:last-child{border-bottom:0}.task-top{display:flex;align-items:flex-start;gap:12px}.task-check{margin:3px 0 0;width:20px;height:20px;min-width:20px;accent-color:var(--accent);cursor:pointer}.task-label{display:block;font-size:15px;font-weight:650;cursor:pointer;line-height:1.4}.kind{font-size:11px;font-weight:650;display:inline-block;border:1px solid var(--line);color:var(--muted);border-radius:20px;padding:2px 8px;margin-top:6px}.task.done .kind{color:var(--accent);background:#eff8f4;border-color:#d9e9df}.task.done .task-label{color:#365953}.task details{margin:9px 0 0 32px}summary{cursor:pointer;font-size:12px;color:var(--muted);width:fit-content}details p{font-size:13px;color:var(--muted);margin:10px 0;white-space:pre-wrap}textarea{display:block;width:100%;min-height:65px;resize:vertical;border:1px solid var(--line);border-radius:7px;padding:9px;color:var(--ink);font:13px/1.45 system-ui;background:#fafcfc;margin-top:6px}.note-label{font-size:12px;color:var(--muted);display:block;margin-top:11px}pre{overflow-x:auto;font-size:12px;padding:11px 12px;border-radius:7px;background:#f1f5f5;border:1px solid var(--line);white-space:pre-wrap;overflow-wrap:anywhere}.empty{padding:14px 18px;font-size:13px;color:var(--muted);margin:0}.footer{font-size:12px;color:var(--muted);padding-top:16px;border-top:1px solid var(--line);margin-top:28px}.footer p{margin:7px 0}.footer a{color:var(--accent)}.warning{color:#8e3d18}.noscript{padding:16px;background:#fff2de} @media(max-width:600px){main{padding:25px 15px 40px}.task{padding:13px}.toggle{margin-left:0}.progress-title{display:block}.progress-title span{display:block;margin-top:3px}.task-label{font-size:14px}.repo{font-size:11px}}\n\n.context a,.task details a{color:var(--accent);text-underline-offset:3px}.task-links{display:flex;gap:12px;flex-wrap:wrap}\n</style></head>\n<body><main><header><div class="eyebrow">Speed of Sound / Versioned handoff</div><h1>Delivery and upstream checklist.</h1><p class="intro">The tested fixes are delivered. Upstream acceptance and the native dependency remain separate gates. Edit checklist.json and run render_checklist.py to update the committed checklist.</p></header>\n<noscript><p class="noscript">JavaScript enables interactive checkboxes. CHECKLIST.md contains the same recorded state.</p></noscript>\n<section class="context"><strong>Target: <code>__TARGET__</code></strong><p>Validated application baseline: <code>__BASE__</code>. The handoff is a documentation-only descendant; use Git for the current branch tip. The installed desktop app was not replaced.</p><p>Rechecked: __REVIEWED__. Tests and evidence are in HANDOFF.md and verification.json. This is not an upstream merge approval.</p></section>\n<section class="context" aria-label="Outstanding native dependency"><strong>OPEN — sherpa-onnx and longer audio</strong><p>__DEPENDENCY__</p><p>PR #3976 merged after v1.13.8. A version bump alone is not acceptance: verify the fix is included, update all Java/native JARs and checksums, and test long audio. See the unchecked dependency item below.</p></section>\n<section class="progress-card" aria-label="Checklist progress"><div class="progress-title"><strong id="progress-text">__DONE__ of __TOTAL__ checkpoints complete</strong><span>Completed engineering is not upstream acceptance.</span></div><progress id="progress" max="__TOTAL__" value="__DONE__" aria-label="Tasks complete"></progress><p class="progress-note">Standard tests and downstream CI are complete for the baseline; open gates are not silently waived.</p></section>\n<div class="toolbar"><button class="primary" id="save-copy" type="button">Save a checklist copy</button><button id="export" type="button">Export progress</button><label class="toggle"><input id="hide" type="checkbox">Hide completed</label></div>\n<p class="save-status" id="save-status" role="status" aria-live="polite"></p><div id="phases"></div>\n<footer class="footer"><p>Local-only tracker: no Git commands or network requests. Browser notes do not automatically update the repository, Markdown, another agent, or this chat. Review exported progress against evidence before editing the canonical JSON. Do not store tokens, settings files, or raw portal logs.</p><p>Reference: HANDOFF.md, CHECKLIST.md, checklist.json and verification.json alongside this file. Historical downloads and earlier reports are superseded where they conflict with this dated handoff.</p></footer></main>\n<script id="initial-data" type="application/json">__DATA__</script><script>\n\'use strict\';\nconst initial = JSON.parse(document.getElementById(\'initial-data\').textContent);\nconst storageKey = \'sos-upstream-checklist-\' + initial.snapshot;\nlet state = structuredClone(initial);\nlet storageOK = true;\ntry {\n  const saved = JSON.parse(localStorage.getItem(storageKey) || \'null\');\n  if (saved && saved.schema === 1 && saved.snapshot === initial.snapshot &&\n      Array.isArray(saved.tasks) && Date.parse(saved.updatedAt) >= Date.parse(initial.updatedAt)) {\n    for (const task of state.tasks) {\n      const match = saved.tasks.find(t => t.id === task.id);\n      if (match) { task.done = match.done === true; task.notes = typeof match.notes === \'string\' ? match.notes : \'\'; }\n    }\n    state.hideCompleted = saved.hideCompleted === true;\n    state.updatedAt = saved.updatedAt;\n  }\n} catch (_) { storageOK = false; }\nconst $ = id => document.getElementById(id);\nfunction storageMessage() {\n  $(\'save-status\').textContent = storageOK ? \'Saved locally in this browser. Use “Save a checklist copy” to preserve progress in a portable file.\' : \'Browser storage is unavailable. Use “Save a checklist copy” before closing to preserve your progress.\';\n  $(\'save-status\').classList.toggle(\'warning\', !storageOK);\n}\nfunction persist() {\n  state.updatedAt = new Date().toISOString();\n  try { localStorage.setItem(storageKey, JSON.stringify(state)); storageOK = true; }\n  catch (_) { storageOK = false; }\n  storageMessage();\n}\nfunction el(tag, className, text) {\n  const n = document.createElement(tag);\n  if (className) n.className = className;\n  if (text !== undefined) n.textContent = text;\n  return n;\n}\nfunction render() {\n  const focusID = document.activeElement ? document.activeElement.id : \'\';\n  const expanded = new Set([...document.querySelectorAll(\'details[open]\')].map(d => d.dataset.task));\n  const completed = state.tasks.filter(t => t.done).length;\n  $(\'progress-text\').textContent = completed + \' of \' + state.tasks.length + \' checkpoints complete\';\n  $(\'progress\').max = state.tasks.length; $(\'progress\').value = completed;\n  $(\'hide\').checked = state.hideCompleted;\n  const holder = $(\'phases\'); holder.replaceChildren();\n  const phases = [...new Set(state.tasks.map(t => t.phase))];\n  for (const phase of phases) {\n    const tasks = state.tasks.filter(t => t.phase === phase);\n    const section = el(\'section\', \'phase\');\n    const head = el(\'div\', \'phase-heading\'); head.append(el(\'h2\', \'\', phase));\n    head.append(el(\'span\', \'phase-count\', tasks.filter(t => t.done).length + \' / \' + tasks.length));\n    section.append(head);\n    const list = el(\'div\', \'task-list\'); let visible = 0;\n    for (const task of tasks) {\n      if (state.hideCompleted && task.done) continue;\n      visible++;\n      const row = el(\'article\', \'task\' + (task.done ? \' done\' : \'\')); row.dataset.id = task.id;\n      const top = el(\'div\', \'task-top\');\n      const check = el(\'input\', \'task-check\'); check.type = \'checkbox\'; check.id = \'check-\' + task.id; check.checked = task.done;\n      check.addEventListener(\'change\', () => { task.done = check.checked; persist(); render(); });\n      const text = el(\'div\'); const label = el(\'label\', \'task-label\', task.title); label.htmlFor = check.id; text.append(label);\n      const status = task.done ? (task.recordedDone ? task.kind : \'You marked complete\') : (task.recordedDone ? \'Recheck requested\' : task.kind);\n      text.append(el(\'span\', \'kind\', status)); top.append(check, text); row.append(top);\n      const detail = el(\'details\'); detail.dataset.task = task.id; detail.open = expanded.has(task.id);\n      detail.append(el(\'summary\', \'\', \'Details & notes\'));\n      detail.append(el(\'p\', \'\', task.detail));\n      if (Array.isArray(task.links)) {\n        const links = el(\'p\', \'task-links\');\n        for (const item of task.links) {\n          if (!/^https:\\/\\/github\\.com\\//.test(item.url)) continue;\n          const a = el(\'a\', \'\', item.label); a.href = item.url; a.target = \'_blank\'; a.rel = \'noopener noreferrer\'; links.append(a);\n        }\n        detail.append(links);\n      }\n      if (task.command) { const pre = el(\'pre\'); pre.append(el(\'code\', \'\', task.command)); detail.append(pre); }\n      const noteLabel = el(\'label\', \'note-label\', \'Your notes / result\'); noteLabel.htmlFor = \'notes-\' + task.id;\n      const notes = el(\'textarea\'); notes.id = noteLabel.htmlFor; notes.value = task.notes;\n      notes.placeholder = \'Record the result or issue / PR number. No credentials.\';\n      notes.addEventListener(\'input\', () => { task.notes = notes.value; persist(); });\n      detail.append(noteLabel, notes); row.append(detail); list.append(row);\n    }\n    if (!visible) list.append(el(\'p\', \'empty\', \'All recorded complete. Uncheck “Hide completed” to review.\'));\n    section.append(list); holder.append(section);\n  }\n  if (focusID && $(focusID)) $(focusID).focus({preventScroll:true});\n}\nfunction download(blob, name) {\n  const url = URL.createObjectURL(blob); const a = document.createElement(\'a\');\n  a.href = url; a.download = name; document.body.append(a); a.click(); a.remove();\n  setTimeout(() => URL.revokeObjectURL(url), 1000);\n}\n$(\'hide\').addEventListener(\'change\', e => { state.hideCompleted = e.target.checked; persist(); render(); });\n$(\'export\').addEventListener(\'click\', () => {\n  persist(); download(new Blob([JSON.stringify(state, null, 2)], {type:\'application/json\'}), \'checklist-progress-export.json\');\n});\n$(\'save-copy\').addEventListener(\'click\', () => {\n  persist();\n  const clone = document.documentElement.cloneNode(true);\n  clone.querySelector(\'#initial-data\').textContent = JSON.stringify(state).replace(/</g, \'\\\\u003c\');\n  clone.querySelector(\'#phases\').replaceChildren();\n  download(new Blob([\'<!doctype html>\\n\' + clone.outerHTML], {type:\'text/html;charset=utf-8\'}), \'speedofsound-upstream-checklist-saved.html\');\n});\nrender(); persist();\n</script></body></html>\n'

def render(source: Path) -> dict[str, str]:
    state = json.loads(source.read_text(encoding="utf-8"))
    tasks = state["tasks"]
    if len(tasks) != 25 or len({t["id"] for t in tasks}) != 25:
        raise ValueError("Expected the existing 25 unique checkpoint IDs; change the schema deliberately.")
    if any(type(t["done"]) is not bool for t in tasks):
        raise ValueError("Each completion value must be Boolean.")
    complete = sum(t["done"] for t in tasks)
    lines = ["# Speed of Sound — handoff checklist", "",
             f"**{complete} / {len(tasks)} complete.** Reviewed {state['reviewedOn']}.", "",
             "Generated from `checklist.json` by `render_checklist.py`; edit the JSON and regenerate both views.", "",
             f"Target: `{state['target']}`. Validated application baseline: `{state['applicationBaseline']}`.", "",
             "This handoff is committed above that baseline without changing application code. The current branch tip is obtained from Git, not inferred from this baseline field.", "",
             "## Explicit outstanding dependency", "", "> " + state["criticalDependencyNote"], "",
             "This dated statement does NOT mark the native dependency as updated. Recheck the release and verify PR #3976 inclusion before changing the complete library set. The dependency gate below remains open.", ""]
    phase = None
    for index, t in enumerate(tasks, 1):
        if t["phase"] != phase:
            phase = t["phase"]
            lines += ["## " + phase, ""]
        lines += [f"- [{'x' if t['done'] else ' '}] **{index:02d}. {t['title']}** (`{t['id']}`)", "",
                  "  **" + t["kind"] + ".** " + t["detail"].replace("\n", "\n  "), ""]
        if t.get("notes"):
            lines += ["  Notes: " + t["notes"].replace("\n", "\n  "), ""]
    lines += ["## Counting and delivery boundaries", "",
              "Model-reload engineering and delivery are complete. Upstream incorporation belongs to the separate contribution-route gate. All four substantive downstream CI workflows passed on the application baseline; they are not the eventual upstream PR's checks. Do not add or remove checkmarks merely to represent preparation of this handoff.", "",
              "Browser checkbox edits are local and are not automatically synchronized to this JSON or GitHub. HANDOFF.md carries the workflow, source/evidence map, preserved limitations and cleanup rules.", ""]
    replacements = {"__TARGET__": html.escape(state["target"]),
                    "__BASE__": html.escape(state["applicationBaseline"][:7]),
                    "__REVIEWED__": html.escape(state["reviewedOn"]),
                    "__DEPENDENCY__": html.escape(state["criticalDependencyNote"]),
                    "__DONE__": str(complete), "__TOTAL__": str(len(tasks)),
                    "__DATA__": json.dumps(state, ensure_ascii=False).replace("<", "\\u003c")}
    page = HTML_TEMPLATE
    for key, value in replacements.items():
        page = page.replace(key, value)
    return {"CHECKLIST.md": "\n".join(lines), "checklist.html": page}

def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if the checked-in views differ from JSON.")
    args = parser.parse_args()
    root = Path(__file__).resolve().parent
    outputs = render(root / "checklist.json")
    mismatches = []
    for name, content in outputs.items():
        path = root / name
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                mismatches.append(name)
        else:
            path.write_text(content, encoding="utf-8")
    if mismatches:
        raise SystemExit("Checklist drift: " + ", ".join(mismatches))
    print("Checklist views match JSON." if args.check else "Rendered CHECKLIST.md and checklist.html.")

if __name__ == "__main__":
    main()
